const r = await Promise.allSettled([
  tools.exec_command({cmd:"rg -n \"groups:view:users|privileges\\.global\\.can|Guest\" src test tests 2>/dev/null | head -200",workdir:"/app",max_output_tokens:6000}),
  tools.exec_command({cmd:"rg -n \"getUidByUsername|getUidByUserslug|userslug|user/.*slug|/user/\" src/controllers src/routes src/user src/privileges test tests 2>/dev/null | head -240",workdir:"/app",max_output_tokens:7000}),
  tools.exec_command({cmd:"rg --files src test tests 2>/dev/null | rg '(privileges|user|well-known|routes|controllers)' | head -160",workdir:"/app",max_output_tokens:3000})
]);
r.forEach((x,i)=>text(JSON.stringify({i, status:x.status, output:x.status==="fulfilled"?x.value.output:String(x.reason)})));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"grep -RInE 'groups:view:users|privileges\\.global\\.can|Guest' src test tests 2>/dev/null | head -200",workdir:"/app",max_output_tokens:8000}),
  tools.exec_command({cmd:"grep -RInE 'getUidByUsername|getUidByUserslug|userslug|/user/' src/controllers src/routes src/user src/privileges test tests 2>/dev/null | head -240",workdir:"/app",max_output_tokens:9000}),
  tools.exec_command({cmd:"find src test tests -type f 2>/dev/null | grep -E '(privileges|user|well-known|routes|controllers)' | head -160",workdir:"/app",max_output_tokens:4000})
]);
r.forEach((x,i)=>text(JSON.stringify({i, status:x.status, output:x.status==="fulfilled"?x.value.output:String(x.reason)})));

